package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StringEscapeUtils.escapeJava(Writer out, String str)
 */
public class StringEscapeUtils_escapeJava_TriageGen5Test {

    @Test
    public void testEscapeJava_NullString() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, null);
        assertEquals("", out.toString());
    }

    @Test
    public void testEscapeJava_EmptyString() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "");
        assertEquals("", out.toString());
    }

    @Test
    public void testEscapeJava_RegularString() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "Hello World");
        assertEquals("Hello World", out.toString());
    }

    @Test
    public void testEscapeJava_SpecialCharacters() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "Line 1\nLine 2\tTab's \"Quotes\"");
        // Expected: Line 1\nLine 2\tTab's \"Quotes\"
        // Note: Depending on exact implementation of escapeJavaStyleString, 
        // single quotes might not be escaped, but double quotes and control chars are.
        assertEquals("Line 1\\nLine 2\\tTab's \\\"Quotes\\\"", out.toString());
    }

    @Test
    public void testEscapeJava_Backslashes() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "C:\\Users\\Name");
        assertEquals("C:\\\\Users\\\\Name", out.toString());
    }

    @Test
    public void testEscapeJava_UnicodeCharacters() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "\u0000\u001F\u2022");
        // \u0000 -> \u0000, \u001F -> \u001f, \u2022 -> \u2022
        assertEquals("\\u0000\\u001f\\u2022", out.toString());
    }

    @Test
    public void testEscapeJava_ControlCharacters() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "\b\r\f");
        assertEquals("\\b\\r\\f", out.toString());
    }

    @Test(expected = IOException.class)
    public void testEscapeJava_ThrowsIOException() throws IOException {
        // Custom Writer that always throws IOException to test error propagation
        Writer throwingWriter = new Writer() {
            @Override
            public void write(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("Simulated IO Failure");
            }

            @Override
            public void flush() throws IOException {}

            @Override
            public void close() throws IOException {}
        };
        StringEscapeUtils.escapeJava(throwingWriter, "test");
    }
}
